-- Airlinerra Phase 5 operating-gate pilot 01, captured in Supabase 26 October 2026.
-- Idempotent archival replay of six research-only airport gate assessments.
-- Requires docs/sql/AIRLINERRA_PHASE5_FALLON_CLARIFICATION_AND_OPERATING_PILOT_01_SCHEMA_2026-10-26.sql
-- Every unspecified commercial permission, carrier, aircraft, flight-date NOTAM and ground-response gate remains NOT_VERIFIED.
-- Airport admission constrained to NOT_APPROVED; public website descriptions are NOT legal consent.
INSERT INTO airlinerra.airport_faa_operational_pilot_reviews
(evidence_cycle, airport_key, faa_identifier, pilot_batch, review_role, nominated_runway_pair, runway_evidence_class, technical_evidence_note, owner_airport_rules_note, fuel_service_evidence_note, operational_constraints_note, next_validation_action, source_urls) VALUES
('2026-10-01', 'OURAIRPORTS:19878', 'FLX', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'PARTIAL_DECLARED_DISTANCE_EXCEPTION', '03/21', 'PARTIAL_DECLARED_DISTANCE_HOLD', 'Oct 1 FAA-derived 03/21 good asphalt 5705x75ft; RW03 threshold shifted 102ft. TORA and TODA 5703ft both directions, no published LDA; separate dirt runway 13/31 3581ft is ineligible. The Sept03-Oct29 Chart Supplement confirms missing LDA despite published takeoff distances.', 'City of Fallon is airport owner/operator, with airport office and FBO contacts listed. Public use does not constitute written authorization to operate paid scheduled or charter airline flights; no written authorization obtained.', 'FAA-derived airport directory and FAA Chart Supplement list 100LL and Jet A service; future service availability, delivery agreements, after-hours ground-handling and selected aircraft readiness not confirmed.', 'Uncontrolled airport, Navy Fallon approach interaction, nearby naval military jet/ultralight traffic, blocked line of sight between RW03 and RW13; obtain date-specific NOTAM, weather, FICON and flight-specific performance. No flight or aircraft selected.', 'Written FAA/airport-owner clarification of absent LDA for 03 and 21; then selected aircraft runway/PCN and operations class, named certificated carrier, written owner paid-service rights, ground handling/rescue, intended-date NOTAM.', ARRAY['https://www.airnav.com/airport/FLX','https://www.fallonnevada.gov/fallon-municipal-airport-flx/','https://tallyaero.com/atlas/chart-supplement/SW_396/','https://www.faa.gov/air_traffic/flight_info/aeronav/digital_products/dafd/']::text[]),
('2026-10-01', 'OURAIRPORTS:19990', 'GWR', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'DISTANCE_SCREEN_CANDIDATE', '16/34', 'AIM_ASSUMED_NOT_PUBLISHED', 'FAA-derived 2026 runway 16/34 5000x75ft good concrete; no numeric LDA or any other declared field, so FAA AIM physical-distance assumption only. Seasonal turf 06/24 2991ft is not game-eligible and its winter closure is not the main runway closure.', 'Gwinner Airport/Roger Melroe Field is unattended according to current Chart Supplement; 24h self-service fuel does not prove staffed owner permission for airline paid flights. No signed airport commercial agreement or named operating certificate.', 'Chart Supplement notes 100LL and Jet A 24h self-service with card. Automated fuel availability does not verify delivery, winter supply reliability, rescue, ground service or contracted airframe support.', 'North Dakota snow/FICON and wildlife. Chart Supplement directs checking winter condition and primary runway snow removal by phone; do not infer a real-time winter clearance. Notam weather and aircraft suitability unverified.', 'Contact owner airport manager regarding snow removal and required commercial permission, nominated aircraft 5000x75 concrete and S14000/D19000 pavement ratings, contracted winter rescue/handling and carrier certification, flight-day NOTAM and FICON.', ARRAY['https://tallyaero.com/atlas/chart-supplement/NC_338/','https://www.airnav.com/airport/GWR']::text[]),
('2026-10-01', 'OURAIRPORTS:20068', 'HND', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'DISTANCE_SCREEN_CANDIDATE', '17R/35L', 'AIM_ASSUMED_NOT_PUBLISHED', 'FAA-derived Oct runways 17R/35L 6501x100ft and shorter 17L/35R 5001x75ft, asphalt, no per-end published LDA. Longest runway is preliminary AIM-assumed screen only; aircraft performance/load and apron/taxi suitability unspecified.', 'Airport operated within Clark County airport system; public airport/FBO website advertises aircraft services. Special-event landing PPR/fees not authorization of airline paid operations, which needs airport/landlord permission and operator certification.', 'Airport official page lists Jet A full service 0530-2200, 100LL full and self service, FBO 0500-2230, airport open 24h. Flight at 23:00 cannot automatically expect Jet A service; no contractual or after-hours commitments confirmed.', 'Airport official 2026 special event PPR Oct16-23 already PASSED as of Oct26; future Nov17-23 and Dec02-13 require PPR. Airport under LAS Class B with heavy training/business-jet traffic. Actual date NOTAM and selected airframe handling needed.', 'Obtain named operator and agreement for commercial activity, selected aircraft slot/ramp/ground handling/Jet A schedule; review intended date against Nov/Dec event PPR and real-time NOTAM/ATC, aircraft performance and rescue support.', ARRAY['https://www.hnd.aero/','https://www.faa.gov/flight_deck/hnd','https://www.faa.gov/licenses_certificates/airline_certification/135_certification']::text[]),
('2026-10-01', 'OURAIRPORTS:5336', 'PAAQ', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'DISTANCE_SCREEN_CANDIDATE', '16/34', 'PUBLISHED_LDA', 'Palmer ICAO PAAQ matches FAA LID PAQ and government source site 50584. Oct 2026 runway 16/34 6006x100ft asphalt, published landing distances RW16 5506ft with 503ft displacement, RW34 6006ft. Distances pass numeric 1200m screen only. City''s 6008ft length is rounded/different than latest FAA 6006ft; use source-specific distinctions.', 'City of Palmer official airport page says it facilitates flightseeing and air-cargo charters and offers transient stands. This is evidence of activities, not a signed use right for a newly named passenger/cargo airline or verification of a specific certificate holder.', 'Municipal airport page advertises 24h fueling, north/south ramp support and delivery with prior arrangements, on-site maintenance. No specific airline fuel/handling agreement or selected aircraft requirements validated.', 'Cold weather snow/ice and mountain valley approaches; crosswind runway 10/28 3616ft under 1200m and short gravel 16S/34S not eligible. Actual NOTAM/FICON, aircraft load and operating season not verified.', 'Obtain written commercial operating permission from City of Palmer, verify named FAA-certificate-holder/OpSpecs, aircraft at max landing/takeoff weights vs 100ft width/PCN, winter NOTAM/FICON weather and FBO fueling, scheduled aircraft rescue for intended flight.', ARRAY['https://www.palmerak.org/airport','https://www.airnav.com/airport/PAQ','https://www.transportation.gov/policy/aviation-policy/licensing/US-carriers']::text[]),
('2026-10-01', 'OURAIRPORTS:20867', 'PRO', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'DISTANCE_SCREEN_CANDIDATE', '14/32', 'AIM_ASSUMED_NOT_PUBLISHED', 'Oct FAA government source and Iowa DOT list main 5500x100ft concrete runway 14/32, no source-published LDA, no reported displacement; 5500ft is only an AIM-assumed screening value. Secondary 04/22 turf 2321-2322ft ineligible. City airport website still states older 4000ft paved length: stale/contradictory municipal page requiring owner acknowledgement.', 'City of Perry official page advertises charter flights and other aeronautical services but no identified operating certificate, signed airport paid-scheduled-use agreement or proof of access for a nominated airline is in this review.', 'Iowa DOT and city airport pages advertise 100LL/Jet A (city says 24/7), but contract, supply continuity, service staff and selected aircraft fueling compatibility not established.', 'Skydiving nearby; verify operations and date NOTAM. Original city runway length 4000ft conflicts with current State/FAA 5500ft. No chosen aircraft, operator or intended flight date.', 'Obtain current city airport manager written confirmation of reconstructed 5500ft concrete runway and commercial flight rights, certificate/OpSpecs for a named carrier, nominated aircraft runway load and performance, date-based NOTAM/skydiving and emergency support.', ARRAY['https://opmapps.iowadot.gov/aviation/airports/PRO','https://www.perryia.org/perry-municipal-airport.html','https://publications.iowa.gov/52348/1/917-2025-2026%20Airport%20Directory-WEB.pdf']::text[]),
('2026-10-01', 'OURAIRPORTS:20921', 'RDK', 'US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26', 'DISTANCE_SCREEN_CANDIDATE', '05/23', 'AIM_ASSUMED_NOT_PUBLISHED', 'Oct FAA source + Iowa DOT: runway 05/23 5100x75ft concrete. RW05 displaced threshold 1000ft => AIM-assumed 4100ft, not published LDA. RW23 assumed full 5100ft. Short concrete 17/35 and winter-closed turf 13/31 do not disqualify main.', 'Municipal airport official Iowa DOT directory identifies airport manager; no signed paid scheduled or charter airline use authorization nor named certified commercial air operator has been produced.', 'State airport directory lists both 100LL and Jet A; no proof of guaranteed fuel, fuel delivery, handling or ARFF for a particular flight.', 'Seasonal turf closure is RW13/31 only; short runway 17/35 independent; ultralight activity and approach obstacles. RW05 marginal effective assumed distance requires aircraft-specific landing margins, NOTAM and operating conditions.', 'Revalidate RW05 1000ft threshold shift and runway use with airport manager, obtain paid-air-carrier right and named FAA/DOT operator authorization; nominate airplane to evaluate runway load/75ft width and RW05 landing distance, arrange service and date-valid NOTAM.', ARRAY['https://secure.iowadot.gov/aviation/data_driven/publications/mapinfosys/AirportDirectory.aspx?FAACode=RDK','https://www.airnav.com/airport/RDK','https://www.transportation.gov/policy/aviation-policy/licensing/US-carriers']::text[])
ON CONFLICT(evidence_cycle,airport_key,pilot_batch) DO NOTHING;

SELECT faa_identifier,nominated_runway_pair,review_role,assessment_status,game_admission_status
FROM airlinerra.airport_faa_operational_pilot_reviews
WHERE pilot_batch='US_PHASE5_OPERATING_GATES_PILOT_01_2026_10_26'
ORDER BY faa_identifier;
